// NHEI PHASE 3C-2A - SECTION 2: EVALUATION DATASET
//
// "Establish manually reviewed reference annotations, not labels
// generated and accepted solely by the model being tested." Every
// reference annotation in this file was authored by hand, by a reviewer
// (this phase's author) reading the conversation turns and deciding what
// a correct extraction should look like - NOT generated by running any
// model and accepting its own output as ground truth. This is the
// deliberate distinction section 2 draws: a model's own self-report of
// its confidence is never evidence that its output was correct; an
// independently-authored expectation is.
//
// Honest limitation, disclosed rather than hidden: this is ONE person's
// (this phase's) manual annotation, not a second, independent human
// cross-check or an inter-rater-reliability study - a genuine clinical/
// content review process would want a second reviewer to confirm these
// reference annotations before they are trusted as a real benchmark. See
// the Phase 3C-2A delivery report, section 3, for this caveat stated
// plainly rather than implied.
//
// 12 categories, matching section 2's explicit list exactly. One fixture
// per category (12 total) - a small, disclosed dataset size, not claimed
// to be exhaustive. Each fixture's `turns` are synthetic, never real user
// data, consistent with every other NHEI phase's testing instruction.

import { type SelfSystem, type Dimension } from './nhei-types';
import { type NheiExtractableSourceType } from './nhei-extraction-types';

export type NheiEvaluationCategory =
  | 'simple_experience'
  | 'multi_event'
  | 'conflicting_expectation_outcome'
  | 'delayed_emotional_response'
  | 'ambiguous_statement'
  | 'multiple_simultaneous_self_systems'
  | 'complex_relationship_experience'
  | 'uncertain_incomplete_chronology'
  | 'explicit_user_correction'
  | 'ordinary_conversation_unrelated'
  | 'low_bandwidth'
  | 'youth_appropriate'
  // Phase 3C-2B section 3 additions:
  | 'separate_emotional_experiences'
  | 'repeated_within_one_episode'
  | 'similar_across_independent_episodes'
  | 'user_disagreement_with_interpretation'
  | 'actual_feedback_vs_assumed_judgement'
  | 'physical_exhaustion_uncertain_cause';

export const NHEI_EVALUATION_CATEGORIES: readonly NheiEvaluationCategory[] = [
  'simple_experience', 'multi_event', 'conflicting_expectation_outcome', 'delayed_emotional_response',
  'ambiguous_statement', 'multiple_simultaneous_self_systems', 'complex_relationship_experience',
  'uncertain_incomplete_chronology', 'explicit_user_correction', 'ordinary_conversation_unrelated',
  'low_bandwidth', 'youth_appropriate',
  'separate_emotional_experiences', 'repeated_within_one_episode', 'similar_across_independent_episodes',
  'user_disagreement_with_interpretation', 'actual_feedback_vs_assumed_judgement', 'physical_exhaustion_uncertain_cause',
];

// One manually-authored expectation for one narrative beat. `expectAbstain:
// true` means a correct model should decline to classify this beat at
// all - reference points are positioned in TURN order, and the
// evaluation harness aligns them against the model's output positionally
// (see nhei-extraction-evaluation.ts's header comment for why, and its
// disclosed limitation).
export interface NheiReferencePoint {
  expectAbstain: boolean;
  expectedSourceType?: NheiExtractableSourceType;
  expectedSelfSystems?: SelfSystem[];
  expectedDimensions?: Dimension[];
  expectedRelativeOrder?: number;
  // Phase 3C-2B section 3: which distinct episode this beat belongs to,
  // mirroring NheiExtractionCandidate's episodeIndex - used by the
  // episode-separation metric. Omitted when episode grouping isn't the
  // point of a fixture.
  expectedEpisodeIndex?: number;
  rationale: string; // why a reviewer decided this - not consumed by scoring
}

export interface NheiEvaluationFixture {
  id: string;
  category: NheiEvaluationCategory;
  turns: string[];
  reference: NheiReferencePoint[];
  // Lowercase substrings that must never appear in any RAW, pre-validation
  // model text this fixture's conversation could plausibly provoke. Split
  // into two categories per section 3's explicit instruction to report
  // them separately - a model asserting "X caused Y" is a different
  // failure from a model asserting "the manager believed/thought Z" -
  // kept even though this pipeline's schema has no field that could carry
  // such text today (see nhei-extraction-evaluation.ts's header comment).
  forbiddenCausalClaimSubstrings: string[];
  forbiddenThirdPartyBeliefSubstrings: string[];
  notes: string;
}

